#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE target_handle;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &target_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return IPC::PlatformFileForTransit(target_handle);
#else
    int target_fd = dup(handle);
    if (target_fd == -1) {
        return IPC::InvalidPlatformFileForTransit();
    }

    if (close_source_handle && (handle != target_fd)) {
        close(handle);
    }

    return IPC::PlatformFileForTransit(target_fd);
#endif
}

#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
  HANDLE target_process = static_cast<HANDLE>(process);
  HANDLE duplicated_handle;
  if (!DuplicateHandle(GetCurrentProcess(), handle, target_process, &duplicated_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
    return IPC::InvalidPlatformFileForTransit();
  }
  return static_cast<IPC::PlatformFileForTransit>(duplicated_handle);
#else
  int flags = O_CLOEXEC;
  int fd = fcntl(handle, F_DUPFD_CLOEXEC, 0);
  if (fd == -1) {
    return IPC::InvalidPlatformFileForTransit();
  }
  // POSIX doesn't require closing the source handle unless explicitly requested.
  if (close_source_handle) {
    close(handle);
  }
  return static_cast<IPC::PlatformFileForTransit>(fd);
#endif
}

