#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileHandle(base::PlatformFile handle, base::ProcessHandle process, bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE duplicate_handle = NULL;
    if (!DuplicateHandle(GetCurrentProcess(), handle, process, &duplicate_handle, 0, FALSE, close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::InvalidPlatformFileForTransit();
    }
    return IPC::PlatformFileForTransit(duplicate_handle);
#else
    int flags = fcntl(handle, F_GETFD);
    if (flags == -1) {
        return IPC::InvalidPlatformFileForTransit();
    }

    if (close_source_handle) {
        flags |= FD_CLOEXEC;
    } else {
        flags &= ~FD_CLOEXEC;
    }

    if (fcntl(handle, F_SETFD, flags) == -1) {
        return IPC::InvalidPlatformFileForTransit();
    }

    return IPC::PlatformFileForTransit(handle);
#endif
}

#include "base/process.h"
#include "base/platform_file.h"
#include "ipc/ipc_platform_file.h"

IPC::PlatformFileForTransit DuplicatePlatformFileForProcess(
    base::PlatformFile handle,
    base::ProcessHandle process,
    bool close_source_handle) {
#if defined(OS_WIN)
    HANDLE duplicated_handle = INVALID_HANDLE_VALUE;
    if (DuplicateHandle(GetCurrentProcess(), handle, process,
                        &duplicated_handle, 0, FALSE,
                        close_source_handle ? DUPLICATE_CLOSE_SOURCE : 0)) {
        return IPC::PlatformFileForTransit(duplicated_handle);
    }
#else
    int flags = close_source_handle ? FD_CLOEXEC : 0;
    int fd = fcntl(handle, F_DUPFD_CLOEXEC, flags);
    if (fd != -1) {
        // Set the close-on-exec flag to avoid leaking the file descriptor to child processes.
        fcntl(fd, F_SETFD, FD_CLOEXEC);
        return IPC::PlatformFileForTransit(fd);
    }
#endif
    return IPC::PlatformFileForTransit();
}
